<?php require_once __DIR__.'/_helpers.php';$ref=pdata('referrals');?><section><div class="page-heading"><div><span class="eyebrow">Monitoring & evaluation</span><h2>Analytics</h2><p>Indicators calculated from seeded JSON.</p></div></div><div class="stat-grid"><div class="stat-card"><span>Reporting completeness</span><strong>83%</strong><small>Demo calculation</small></div><div class="stat-card"><span>On-time reports</span><strong>75%</strong><small>September 2026</small></div><div class="stat-card"><span>Avg reports / CHW</span><strong>1.0</strong><small>Current period</small></div><div class="stat-card"><span>Follow-ups required</span><strong><?=count(array_filter($ref,fn($x)=>$x['follow_up_required']))?></strong><small>Referrals</small></div></div><div class="panel"><h3>District reporting overview</h3><div class="bars"><?php foreach(pdata('districts') as $d){$n=count(array_filter(pdata('chws'),fn($c)=>$c['district_id']===$d['id']));$w=min(100,20+$n*20);?><div class="bar-row"><span><?=htmlspecialchars($d['name'])?></span><div><i style="width:<?=$w?>%"></i></div><b><?=$n?></b></div><?php }?></div></div></section>
